class Password {private final String password;public Password(String password){if(password==null)throw new IllegalArgumentException("Password cannot be null");this.password=password;}public String getStrength(){int length=password.length();if(length<6)return "Weak";else if(length<10)return "Medium";else return "Strong";}}
public class PasswordChecker {public static void main(String[] args){Password pc1=new Password("abcd"),pc2=new Password("abcdefgh"),pc3=new Password("abcdefghijkl");System.out.println(pc1.getStrength());System.out.println(pc2.getStrength());System.out.println(pc3.getStrength());}}